head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gIsurCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        getParaIsurCd = $c.frame.path("../").fn_getParaIsurCd;
        scwin.gIsurCd = getParaIsurCd();
        await scwin.getSkillGrwComGrace();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05245.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Read_OnFail
 * @description Read On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnFail = async function() {
    try {
        await $c.win.alert(trs_Read.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05245.trs_Read_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
        top_list_sync = $c.frame.path("../").fn_list_sync;
        top_list_sync();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05245.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
        await $c.win.alert(trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05245.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name dts_ContentsInfo_OnLoadError
 * @description dts_ContentsInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ContentsInfo_OnLoadError = async function() {
    try {
        await $c.win.alert('dts_ContentsInfo.OnLoadError()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05245.dts_ContentsInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ContentsInfo_OnLoadCompleted
 * @description dts_ContentsInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05245.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description btn_cancel 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05245.btn_cancel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getSkillGrwComGrace
 * @description get Skill Grw Com Grace 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getSkillGrwComGrace = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/SkillGrwComGrace.do",
        ref : "dts_ContentsInfo",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // var operLossYn = getObjectValue(cmb_OPERLOSS_GRACE_YN);

    const rtn = confirm('저장 하시겠습니까?');
    if (rtn === 1) {
        dts_ContentsInfo.setCellData(1, "EMP_NO", js_emp_no);
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/SkillGrwComGrace.do",
            ref : "dts_ContentsInfo",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
